/* Datenschutz-Einstellungen: gleicher Zugang zu Ablehnung und Zustimmung. */
.nf-consent[hidden] { display:none !important; }
.nf-consent { position:fixed; z-index:10000; inset:auto 1rem 1rem; max-width:780px; max-height:85vh; overflow:auto; margin-inline:auto; padding:clamp(1.2rem,3vw,2rem); background:#132639; color:#f3eee7; border:1px solid #61717f; box-shadow:0 10px 50px #0004; font-family:'Public Sans',system-ui,sans-serif; font-size:1rem; line-height:1.6; }
.nf-consent h2 { color:#f3eee7; font-family:'Libre Baskerville',Georgia,serif; font-size:1.5rem; margin:0 0 1rem; }
.nf-consent p { color:#d4dde5; margin:0 0 1rem; }
.nf-consent a { color:#f3b78f; text-decoration:underline; }
.nf-consent label { display:flex; align-items:flex-start; gap:.7rem; color:#f3eee7; margin:1rem 0; }
.nf-consent input { width:1.2rem; height:1.2rem; flex-shrink:0; margin:.3rem 0 0; accent-color:#e08a5a; }
.nf-consent-actions { display:grid; grid-template-columns:1fr 1fr; gap:.8rem; }
.nf-consent-actions button { appearance:none; border:1px solid #d4dde5; border-radius:3px; background:#f3eee7; color:#132639; padding:.8rem 1rem; font:600 .95rem/1.4 'Public Sans',system-ui,sans-serif; cursor:pointer; }
.nf-consent-actions button:last-child { grid-column:1/-1; background:transparent; color:#f3eee7; }
.nf-consent-actions button:hover { background:#e8e1d6; color:#132639; }
.nf-consent-settings { appearance:none; background:transparent; border:0; padding:0; font:inherit; color:inherit; text-decoration:underline; text-underline-offset:.2em; cursor:pointer; }
.nf-consent :focus-visible,.nf-consent-settings:focus-visible { outline:3px solid #e08a5a; outline-offset:4px; }
@media(max-width:480px){.nf-consent{inset:auto .6rem .6rem;}.nf-consent-actions{grid-template-columns:1fr;}}

/* Zweistufiger Cookie-Banner: gleiche Zugänglichkeit von Zustimmung und Ablehnung. */
.nf-consent [hidden] { display:none !important; }
.nf-consent-actions { grid-template-columns:repeat(2,minmax(0,1fr)); }
.nf-consent-actions button:last-child { grid-column:auto; }
#nf-consent-change { grid-column:1/-1; background:transparent; color:#f3eee7; }
.nf-consent:not(.nf-consent-details) #nf-consent-reject { background:transparent; color:#f3eee7; }
.nf-consent:not(.nf-consent-details) #nf-consent-accept { background:#f3eee7; color:#132639; }
.nf-consent-details #nf-consent-change { display:none; }
@media(max-width:480px){.nf-consent-actions{grid-template-columns:1fr;}#nf-consent-change{grid-column:auto;}}

/* Einheitliche Desktop-Navigation auf allen Seiten */
@media (min-width: 1001px) {
  .site-header .site-nav { gap: clamp(.4rem, .8vw, .8rem); }
  .site-header .site-nav > a { white-space: nowrap; flex-shrink: 0; }
}
